def sat_update(c, up, bits):
    # signed saturating up/down counter, the host's ctrupdate
    if up:
        if c < (1 << (bits - 1)) - 1:
            c = c + 1
    else:
        if c > -(1 << (bits - 1)):
            c = c - 1
    return c

def wt_index(pc, d, k, n):
    # pc: branch PC; d: 12-bit digest; k: table 0, 1 or 2; n = log2(table entries)
    pcw = pc >> 2    # AArch64 instructions are 4-byte aligned
    return fold(pcw ^ (pcw >> (n + k + 1)) ^ (d << (3 * k)), n)

def ut_index(pc, k, m):
    # k: usefulness table 0, 1 or 2; m = log2(table entries)
    pcw = pc >> 2
    return fold(pcw ^ (pcw >> (m + k + 1)), m)

def decode_allocate(tag, dest, first_write_of_dest):
    # tag: the piece's in-flight tag (ROB index), tag_bits wide
    # dest: destination logical register, or -1 if none
    # 1. age every visible digest by one decoded instruction
    for r in range(num_logical_regs):
        if reg_status[r].valid == 1:
            if reg_status[r].decay_ctr == 0:
                reg_status[r].valid = 0
                reg_status[r].payload = 0
            else:
                reg_status[r].decay_ctr = reg_status[r].decay_ctr - 1
    # 2. the register's newest producer is now this piece
    if dest >= 0 and dest < num_logical_regs and first_write_of_dest:
        reg_status[dest].valid = 0
        reg_status[dest].payload = tag
        reg_status[dest].decay_ctr = 0

def writeback_digest(tag, dest, v, first_write_of_dest):
    if dest < 0 or dest >= num_logical_regs or not first_write_of_dest:
        return
    # an older producer finishing after a younger one was decoded must not win
    if reg_status[dest].valid == 0 and reg_status[dest].payload == tag:
        reg_status[dest].payload = generate_digest(v, dest)
        reg_status[dest].valid = 1
        reg_status[dest].decay_ctr = (1 << decay_ctr_bits) - 1

def squash_recovery(squashed_tags):
    for r in range(num_logical_regs):
        if reg_status[r].valid == 0 and reg_status[r].payload in squashed_tags:
            reg_status[r].payload = 0    # no later writeback can match it
    for branch_id in squashed_branches:
        release(sr_checkpoint[branch_id])
